const body = $input.first().json.body ?? $input.first().json;

const secretNew = ($env.WEBHOOK_SECRET || '').toString();
const secretOld = ($env.WEBHOOK_SECRET_OLD || '').toString();
const webhookSecret = (body.webhook_secret ?? '').toString().trim();
if (!secretNew) throw new Error('MISSING WEBHOOK_SECRET_env');
if (!webhookSecret) throw new Error('MISSING webhook_secret');
let secret_used = '';
if (webhookSecret === secretNew) secret_used = 'new';
else if (secretOld && webhookSecret === secretOld) secret_used = 'old';
else throw new Error('UNAUTHORIZED');

const tenantId = (body.tenant_id ?? '').toString().trim();
const instanceFromBody = (body.instance_name ?? '').toString().trim();
const instanceName = instanceFromBody;
if (!instanceName) throw new Error('MISSING instance_name');

const raw = Array.isArray(body.messages) ? body.messages : [];
if (raw.length === 0) throw new Error('MISSING messages');

const intervalSeconds = Math.max(5, Number(body.interval_seconds) || 30);
const restEvery = Math.max(0, Number(body.rest_every_messages) || 25);
const restMinutes = Math.max(1, Number(body.rest_minutes) || 5);

const messages = [];
for (const m of raw) {
  const phoneRaw = (m.customer_phone ?? '').toString().trim();
  let digits = phoneRaw.replace(/\D/g, '');
  if (digits.startsWith('0')) digits = '964' + digits.slice(1);
  else if (digits.length === 10 && digits.startsWith('7')) digits = '964' + digits;
  const text = (m.message_text ?? '').toString().trim();
  if (!digits || !text) continue;
  messages.push({
    phone: digits,
    message_text: text,
    order_id: m.order_id ?? null,
    customer_name: (m.customer_name ?? '').toString(),
  });
}

if (messages.length === 0) throw new Error('NO_VALID_MESSAGES');

return [{
  json: {
    instanceName,
    secret_used,
    tenant_id: tenantId,
    accepted: messages.length,
    interval_seconds: intervalSeconds,
    rest_every_messages: restEvery,
    rest_minutes: restMinutes,
    messages,
  },
}];

const root = $input.first().json;
const messages = Array.isArray(root.messages) ? root.messages : [];
const instance = (root.instanceName || '').toString();
const evolutionBase = ($env.EVOLUTION_BASE_URL || 'http://72.61.191.237:8080').replace(/\/$/, '');
const apiKey = $env.EVOLUTION_API_KEY;

const intervalMs = Math.max(5, Number(root.interval_seconds) || 30) * 1000;
const restEvery = Math.max(0, Number(root.rest_every_messages) || 25);
const restMs = Math.max(1, Number(root.rest_minutes) || 5) * 60 * 1000;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const results = [];
for (let i = 0; i < messages.length; i++) {
  const item = messages[i] || {};
  const phone = (item.phone || '').toString();
  const text = (item.message_text || '').toString();
  let ok = false;
  let reason = '';
  try {
    if (!phone || !text) {
      reason = 'missing_phone_or_text';
    } else {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${evolutionBase}/message/sendText/${instance}`,
        headers: {
          apikey: apiKey,
          'Content-Type': 'application/json',
        },
        body: { number: phone, text },
        json: true,
        timeout: 30000,
      });
      ok = true;
    }
  } catch (e) {
    reason = (e.message || String(e)).slice(0, 200);
  }

  results.push({
    json: {
      phone,
      message_text: text,
      order_id: item.order_id ?? null,
      customer_name: item.customer_name ?? '',
      instanceName: instance,
      send_ok: ok,
      send_reason: reason,
      index: i + 1,
      total: messages.length,
    },
  });

  if (i < messages.length - 1) {
    let waitMs = intervalMs;
    if (restEvery > 0 && (i + 1) % restEvery === 0) {
      waitMs += restMs;
    }
    await sleep(waitMs);
  }
}

return results;
